/** يحوّل الأرقام العربية-الهندية (٠-٩) والفارسية (۰-۹) إلى لاتينية — لوحة مفاتيح الآيفون العربية تكتبها */
function normalizeDigits(value) {
  return String(value == null ? '' : value)
    .replace(/[\u0660-\u0669]/g, d => String(d.charCodeAt(0) - 0x0660))
    .replace(/[\u06F0-\u06F9]/g, d => String(d.charCodeAt(0) - 0x06F0))
    .replace(/\u066B/g, '.')
    .replace(/[\u066C\u060C]/g, '');
}

/** يفتح رابطاً خارجياً (واتساب). سفاري يحظر window.open بعد await؛ عندها نعرض زر ضغطة واحدة بدل الفشل الصامت */
function openExternal(url) {
  let w = null;
  try { w = window.open(url, '_blank'); } catch (e) { w = null; }
  if (w) { try { w.opener = null; } catch (e) { /* تجاهل */ } return; }
  showExternalFallback(url);
}

function showExternalFallback(url) {
  const old = document.getElementById('external-fallback');
  if (old) old.remove();
  const box = document.createElement('div');
  box.id = 'external-fallback';
  box.setAttribute('role', 'dialog');
  const msg = document.createElement('span');
  msg.textContent = 'اضغط للمتابعة إلى واتساب';
  const link = document.createElement('a');
  link.href = url; link.target = '_blank'; link.rel = 'noopener';
  link.textContent = 'فتح واتساب';
  link.addEventListener('click', () => setTimeout(() => box.remove(), 400));
  const close = document.createElement('button');
  close.type = 'button'; close.textContent = 'إغلاق';
  close.addEventListener('click', () => box.remove());
  box.append(msg, link, close);
  document.body.appendChild(box);
  setTimeout(() => { if (box.parentNode) box.remove(); }, 20000);
}

