/* =========================================================================
   عبور إكسبريس — طبقة المصادقة عبر Supabase Auth
   -------------------------------------------------------------------------
   نظام الحساب الآن: بريد إلكتروني + كلمة سر (تديره Supabase Auth بالكامل
   بشكل حقيقي وآمن)، مع رقم هاتف *فريد إجبارياً* يُتحقق منه قبل السماح
   بالتسجيل. هذا يستبدل نظام "الهاتف كاسم مستخدم" التجريبي السابق بنظام
   حقيقي مبني على بنية Supabase القياسية (الأكثر أماناً ودعماً لاسترجاع
   كلمة السر ونحوه من الصندوق مباشرة).
   ========================================================================= */

const UbourAuth = (() => {

  /* ---------------- التحقق من صيغة رقم الهاتف (يمني/سعودي) ---------------- */
  function detectPhone(raw) {
    const digits = normalizeDigits(raw || '').replace(/[^\d+]/g, '').replace(/^00/, '+');
    const yemenLocal = /^0?7\d{8}$/;
    const yemenIntl = /^\+?9677\d{8}$/;
    const saudiLocal = /^0?5\d{8}$/;
    const saudiIntl = /^\+?9665\d{8}$/;

    if (yemenIntl.test(digits)) return { valid: true, e164: '+967' + digits.replace(/^\+?967/, ''), country: 'اليمن' };
    if (yemenLocal.test(digits)) return { valid: true, e164: '+967' + digits.replace(/^0/, ''), country: 'اليمن' };
    if (saudiIntl.test(digits)) return { valid: true, e164: '+966' + digits.replace(/^\+?966/, ''), country: 'السعودية' };
    if (saudiLocal.test(digits)) return { valid: true, e164: '+966' + digits.replace(/^0/, ''), country: 'السعودية' };
    return { valid: false };
  }

  function passwordStrength(pw) {
    if (!pw) return 0;
    let score = 0;
    if (pw.length >= 8) score++;
    if (/[A-Za-z]/.test(pw) && /\d/.test(pw)) score++;
    if (pw.length >= 12 && /[^A-Za-z0-9]/.test(pw)) score++;
    return Math.min(score, 3);
  }

  /* ---------------- التسجيل: بريد + كلمة سر + هاتف فريد ---------------- */
  /**
   * الخطوات: 1) التحقق من صيغة الهاتف  2) التأكد أن الهاتف غير مسجّل
   * مسبقاً عبر جدول profiles (وإلا رفض التسجيل فوراً كما طُلب)
   * 3) إنشاء حساب Supabase Auth بالبريد وكلمة السر، مع تمرير رقم الهاتف
   * ضمن بيانات المستخدم الوصفية (user_metadata) — يقرأه Trigger على
   * مستوى القاعدة (handle_new_user في supabase-schema.sql) فيُنشئ سطر
   * profiles تلقائياً وفورياً، بغض النظر عن حالة الجلسة (يعمل صحيحاً حتى
   * لو كان تأكيد البريد الإلكتروني مفعّلاً ولا توجد جلسة دخول بعد).
   */
  async function signUp({ phoneRaw, email, password }) {
    const phoneResult = detectPhone(phoneRaw);
    if (!phoneResult.valid) return { ok: false, error: 'INVALID_PHONE' };

    const exists = await UbourDB.checkPhoneExists(phoneResult.e164);
    if (exists) return { ok: false, error: 'DUPLICATE_PHONE' };

    const { data, error } = await supabaseClient.auth.signUp({
      email, password,
      options: { data: { phone: phoneResult.e164 } }
    });
    if (error) {
      if (error.message && error.message.toLowerCase().includes('already registered')) {
        return { ok: false, error: 'DUPLICATE_EMAIL' };
      }
      return { ok: false, error: 'SIGNUP_FAILED', message: error.message };
    }
    if (!data.user) return { ok: false, error: 'SIGNUP_FAILED' };

    return { ok: true, userId: data.user.id, phone: phoneResult.e164, country: phoneResult.country, needsEmailConfirm: !data.session };
  }

  /* ---------------- تسجيل الدخول: رقم الجوال + كلمة السر فقط ----------------
   * المستخدم لا يرى البريد الإلكتروني إطلاقاً بعد التسجيل الأول. نحوّل
   * الرقم داخلياً إلى البريد المرتبط به عبر دالة RPC آمنة في القاعدة
   * (get_email_by_phone)، ثم نكمل الدخول الحقيقي عبر Supabase Auth بنفس
   * البريد وكلمة السر التي كتبها المستخدم. كلمة السر نفسها لا تُفحص إلا
   * من طرف Supabase Auth، فلا يمكن لأي شخص الدخول لحساب غيره حتى لو عرف
   * رقم جواله، لأنه لا يعرف كلمة سره. */
  async function signIn(phoneRaw, password) {
    const phoneResult = detectPhone(phoneRaw);
    if (!phoneResult.valid) return { ok: false, error: 'INVALID_PHONE' };

    let data;
    const edge = await UbourDB.edgeAuth({ action: 'login', phone: phoneResult.e164, password });
    if (!edge.unavailable) {
      if (edge.status === 429) return { ok: false, error: 'RATE_LIMITED' };
      const sess = edge.data && edge.data.session;
      if (!sess) return { ok: false, error: 'INVALID_CREDENTIALS' };
      const r = await supabaseClient.auth.setSession({ access_token: sess.access_token, refresh_token: sess.refresh_token });
      if (r.error || !r.data || !r.data.user) return { ok: false, error: 'INVALID_CREDENTIALS' };
      data = r.data;
    } else {
      if (!APP_CONFIG.allowLegacyPhoneLookup) return { ok: false, error: 'SERVICE_UNAVAILABLE' };
      const email = await UbourDB.getEmailByPhone(phoneResult.e164);
      if (!email) return { ok: false, error: 'INVALID_CREDENTIALS' };   // رسالة موحّدة: لا نكشف إن كان الرقم مسجّلاً
      const r = await supabaseClient.auth.signInWithPassword({ email, password });
      if (r.error) return { ok: false, error: 'INVALID_CREDENTIALS' };
      data = r.data;
    }
    // ترميم احتياطي: إن أُنشئ السجل دون رقم هاتف (تأخر الـ Metadata) نكمله الآن
    try {
      const { data: prof } = await supabaseClient.from('profiles').select('phone').eq('id', data.user.id).maybeSingle();
      if (prof && !prof.phone) await supabaseClient.from('profiles').update({ phone: phoneResult.e164 }).eq('id', data.user.id);
    } catch (e) { console.error(e); }
    return { ok: true, userId: data.user.id };
  }

  /* ---------------- نسيت كلمة السر: عبر رقم الجوال ---------------- */
  /** يحوّل الرقم إلى بريده داخلياً، ثم يطلب من Supabase إرسال رابط إعادة
   *  التعيين الحقيقي إلى ذلك البريد (المستخدم لا يكتب بريده أبداً) */
  async function requestPasswordResetByPhone(phoneRaw) {
    const phoneResult = detectPhone(phoneRaw);
    if (!phoneResult.valid) return { ok: false, error: 'INVALID_PHONE' };

    const redirectTo = window.location.origin + window.location.pathname;
    const edge = await UbourDB.edgeAuth({ action: 'reset', phone: phoneResult.e164, redirectTo });
    if (!edge.unavailable) {
      if (edge.status === 429) return { ok: false, error: 'RATE_LIMITED' };
      return { ok: true };            // نفس الرد دائماً سواء كان الرقم مسجّلاً أم لا
    }
    if (!APP_CONFIG.allowLegacyPhoneLookup) return { ok: false, error: 'SERVICE_UNAVAILABLE' };
    const email = await UbourDB.getEmailByPhone(phoneResult.e164);
    if (!email) return { ok: true };  // لا نكشف عدم وجود الرقم
    const { error } = await supabaseClient.auth.resetPasswordForEmail(email, { redirectTo });
    if (error) return { ok: false, error: error.message };
    return { ok: true };
  }

  /** تُستدعى من الصفحة بعد أن يفتح المستخدم رابط إعادة التعيين من بريده */
  async function updatePasswordAfterReset(newPassword) {
    const { error } = await supabaseClient.auth.updateUser({ password: newPassword });
    if (error) return { ok: false, error: error.message };
    return { ok: true };
  }

  /* ---------------- تغيير البريد الإلكتروني ---------------- */
  /** يرسل Supabase بريد تأكيد لكل من العنوان القديم والجديد قبل التفعيل */
  async function changeEmail(newEmail) {
    const { error } = await supabaseClient.auth.updateUser({ email: newEmail });
    if (error) return { ok: false, error: error.message };
    return { ok: true };
  }

  /* ---------------- تغيير كلمة السر (وأنت مسجّل الدخول) ---------------- */
  async function changePassword(newPassword) {
    if (newPassword.length < 8) return { ok: false, error: 'PASSWORD_TOO_SHORT' };
    const { error } = await supabaseClient.auth.updateUser({ password: newPassword });
    if (error) return { ok: false, error: error.message };
    return { ok: true };
  }

  function logout() {
    return UbourDB.endSession();
  }

  return {
    detectPhone,
    passwordStrength,
    signUp,
    signIn,
    requestPasswordResetByPhone,
    updatePasswordAfterReset,
    changeEmail,
    changePassword,
    logout
  };
})();


;
