/* ---------------- التنقل بين الشاشات ---------------- */
const screenHistory = ['screen-splash'];

function showScreen(id, { replace = false } = {}) {
  document.querySelectorAll('.screen').forEach(s => s.classList.remove('active'));
  const el = document.getElementById(id);
  if (!el) return;
  el.classList.add('active');
  if (replace) {
    screenHistory[screenHistory.length - 1] = id;
  } else if (screenHistory[screenHistory.length - 1] !== id) {
    screenHistory.push(id);
  }
  el.scrollTop = 0;
  const scroller = el.querySelector('.home-scroll');
  if (scroller) scroller.scrollTop = 0;
}

function goBack(fallbackId) {
  if (screenHistory.length > 1) {
    screenHistory.pop();
    showScreen(screenHistory[screenHistory.length - 1], { replace: true });
  } else if (fallbackId) {
    showScreen(fallbackId, { replace: true });
  }
}

/* ---------------- نظام التوست (إشعارات صغيرة أسفل الشاشة) ---------------- */
function showToast(message, type = 'info', duration = 3800) {
  const container = document.getElementById('toast-container');
  const toast = document.createElement('div');
  toast.className = `toast ${type}`;
  const icon = type === 'success' ? ICONS.checkCircle : type === 'error' ? ICONS.alertTriangle : ICONS.info;
  const iconEl = document.createElement('span'); iconEl.className = 'toast-icon'; iconEl.innerHTML = icon;
  const msgEl = document.createElement('span'); msgEl.textContent = String(message);
  toast.append(iconEl, msgEl);
  container.appendChild(toast);
  setTimeout(() => {
    toast.classList.add('hide');
    setTimeout(() => toast.remove(), 200);
  }, duration);
}

/* ---------------- أداة: عرض رمز تجريبي (Demo Mode) داخل الشاشة ---------------- */
function showDemoCode(targetEl, code, label) {
  targetEl.innerHTML = `
    ${ICONS.info}
    <div>
      <b>${label}</b>
      وضع تجريبي: لا يوجد إرسال SMS/بريد فعلي بعد. رمزك هو
      <span class="code-flash">${code}</span>
    </div>`;
}

/* ---------------- خانات رمز التحقق (OTP) — تعبئة تلقائية ونسخ/لصق ---------------- */
function setupOtpInputs(containerEl, onComplete) {
  const boxes = Array.from(containerEl.querySelectorAll('.otp-box'));
  boxes.forEach((box, i) => {
    box.addEventListener('input', () => {
      box.value = box.value.replace(/\D/g, '').slice(-1);
      box.classList.remove('error');
      if (box.value && boxes[i + 1]) boxes[i + 1].focus();
      if (boxes.every(b => b.value)) onComplete(boxes.map(b => b.value).join(''));
    });
    box.addEventListener('keydown', (e) => {
      if (e.key === 'Backspace' && !box.value && boxes[i - 1]) {
        boxes[i - 1].focus();
      }
    });
    box.addEventListener('paste', (e) => {
      e.preventDefault();
      const text = (e.clipboardData.getData('text') || '').replace(/\D/g, '');
      if (!text) return;
      text.split('').slice(0, boxes.length).forEach((ch, idx) => { if (boxes[idx]) boxes[idx].value = ch; });
      const next = boxes[Math.min(text.length, boxes.length - 1)];
      if (next) next.focus();
      if (boxes.every(b => b.value)) onComplete(boxes.map(b => b.value).join(''));
    });
  });
}

function clearOtpInputs(containerEl, markError = false) {
  const boxes = Array.from(containerEl.querySelectorAll('.otp-box'));
  boxes.forEach(b => { b.value = ''; if (markError) b.classList.add('error'); });
  if (!markError) boxes[0].focus();
}

/* ---------------- عداد تنازلي لإعادة إرسال الرمز ---------------- */
function startResendTimer(displayEl, buttonEl, seconds) {
  let remaining = seconds;
  buttonEl.disabled = true;
  clearInterval(buttonEl._timerRef);
  const tick = () => {
    displayEl.innerHTML = `يمكنك إعادة الإرسال خلال <strong>${remaining}</strong> ثانية`;
    if (remaining <= 0) {
      clearInterval(buttonEl._timerRef);
      displayEl.textContent = '';
      buttonEl.disabled = false;
    }
    remaining--;
  };
  tick();
  buttonEl._timerRef = setInterval(tick, 1000);
}

/* ---------------- حالة عمل مؤقتة لتذكّر خطوة التسجيل ---------------- */
let currentCountry = null;

/* =========================================================================
   شاشة 1: البداية (Splash)
   ========================================================================= */
function initSplashScreen() {
  document.getElementById('splash-app-name').textContent = APP_CONFIG.nameShort;
  document.getElementById('splash-tagline').textContent = APP_CONFIG.tagline;
  document.getElementById('btn-splash-start').addEventListener('click', () => showScreen('screen-login'));
}

/* =========================================================================
   شاشة 2: تسجيل الدخول (بريد إلكتروني + كلمة سر)
   ========================================================================= */
function initLoginScreen() {
  const phoneInput = document.getElementById('input-login-phone');
  const pwInput = document.getElementById('input-login-password');
  const errorEl = document.getElementById('error-login');
  const btn = document.getElementById('btn-login-submit');

  document.getElementById('btn-login-back').addEventListener('click', () => goBack('screen-splash'));
  document.getElementById('btn-goto-register').addEventListener('click', () => showScreen('screen-register-phone'));
  document.getElementById('btn-forgot-password').addEventListener('click', () => {
    document.getElementById('input-forgot-phone').value = phoneInput.value.trim();
    showScreen('screen-forgot-password');
  });

  async function submitLogin() {
    const phoneRaw = phoneInput.value.trim();
    const password = pwInput.value;
    errorEl.classList.remove('show');
    [document.getElementById('wrap-login-phone'), document.getElementById('wrap-login-password')].forEach(w => w.classList.remove('has-error'));

    if (!phoneRaw || !password) {
      errorEl.textContent = 'يرجى إدخال رقم الجوال وكلمة السر';
      errorEl.classList.add('show');
      return;
    }

    btn.classList.add('loading');
    btn.disabled = true;
    const result = await UbourAuth.signIn(phoneRaw, password);
    btn.classList.remove('loading');
    btn.disabled = false;

    if (!result.ok) {
      if (result.error === 'INVALID_PHONE') {
        errorEl.textContent = 'صيغة رقم الجوال غير صحيحة';
      } else if (result.error === 'RATE_LIMITED') {
        errorEl.textContent = 'محاولات كثيرة، انتظر بضع دقائق ثم حاول مجدداً';
      } else if (result.error === 'SERVICE_UNAVAILABLE') {
        errorEl.textContent = 'الخدمة غير متاحة مؤقتاً، حاول لاحقاً';
      } else {
        errorEl.textContent = 'رقم الجوال أو كلمة السر غير صحيحة';
      }
      errorEl.classList.add('show');
      return;
    }
    showToast(`مرحباً بعودتك إلى ${APP_CONFIG.nameShort} 👋`, 'success');
    await routeUserAfterAuth();
  }

  btn.addEventListener('click', submitLogin);
  pwInput.addEventListener('keydown', (e) => { if (e.key === 'Enter') submitLogin(); });
}

/* =========================================================================
   شاشة 3: التسجيل — الخطوة 1: التحقق من رقم الهاتف
   ========================================================================= */
let _pendingRegPhone = null;
function initRegisterPhoneScreen() {
  const phoneInput = document.getElementById('input-reg-phone');
  const errorEl = document.getElementById('error-reg-phone');
  const btn = document.getElementById('btn-register-phone-continue');

  document.getElementById('btn-register-phone-back').addEventListener('click', () => goBack('screen-login'));

  async function submitRegisterPhone() {
    const raw = phoneInput.value.trim();
    errorEl.classList.remove('show');
    document.getElementById('wrap-reg-phone').classList.remove('has-error');

    const result = UbourAuth.detectPhone(raw);
    if (!result.valid) {
      errorEl.textContent = 'صيغة الرقم غير صحيحة. أدخل رقماً يمنياً (7xxxxxxxx) أو سعودياً (05xxxxxxxx)';
      errorEl.classList.add('show');
      document.getElementById('wrap-reg-phone').classList.add('has-error');
      return;
    }

    btn.classList.add('loading');
    btn.disabled = true;
    const exists = await UbourDB.checkPhoneExists(result.e164);
    btn.classList.remove('loading');
    btn.disabled = false;

    if (exists) {
      errorEl.textContent = 'هذا الرقم مسجّل بالفعل بحساب آخر. جرّب تسجيل الدخول بدلاً من ذلك';
      errorEl.classList.add('show');
      document.getElementById('wrap-reg-phone').classList.add('has-error');
      return;
    }

    _pendingRegPhone = raw;
    showScreen('screen-register-account');
  }

  btn.addEventListener('click', submitRegisterPhone);
  phoneInput.addEventListener('keydown', (e) => { if (e.key === 'Enter') submitRegisterPhone(); });
}

/* =========================================================================
   شاشة 4: التسجيل — الخطوة 2: البريد وكلمة السر
   ========================================================================= */
function initRegisterAccountScreen() {
  const emailInput = document.getElementById('input-reg-email');
  const pwInput = document.getElementById('input-reg-password');
  const pwConfirm = document.getElementById('input-reg-password-confirm');
  const strengthBar = document.getElementById('pw-strength-bar');
  const strengthLabel = document.getElementById('pw-strength-label');
  const errorEl = document.getElementById('error-reg-account');
  const btn = document.getElementById('btn-create-account');
  const terms = document.getElementById('checkbox-terms');

  document.getElementById('btn-register-account-back').addEventListener('click', () => goBack('screen-register-phone'));

  pwInput.addEventListener('input', () => {
    const score = UbourAuth.passwordStrength(pwInput.value);
    strengthBar.className = 'pw-strength' + (score === 0 ? '' : score === 1 ? ' weak' : score === 2 ? ' medium' : ' strong');
    const labels = ['أدخل كلمة السر', 'ضعيفة — أضف أرقاماً وحروفاً', 'متوسطة', 'قوية'];
    strengthLabel.textContent = pwInput.value ? labels[score] : '8 أحرف على الأقل، حروف وأرقام';
  });

  async function submitRegisterAccount() {
    errorEl.classList.remove('show');
    [document.getElementById('wrap-reg-email'), document.getElementById('wrap-reg-password'), document.getElementById('wrap-reg-password-confirm')]
      .forEach(w => w.classList.remove('has-error'));

    const email = emailInput.value.trim();
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
      errorEl.textContent = 'يرجى إدخال بريد إلكتروني صحيح';
      errorEl.classList.add('show');
      document.getElementById('wrap-reg-email').classList.add('has-error');
      return;
    }
    if (pwInput.value.length < 8) {
      errorEl.textContent = 'كلمة السر يجب ألا تقل عن 8 أحرف';
      errorEl.classList.add('show');
      document.getElementById('wrap-reg-password').classList.add('has-error');
      return;
    }
    if (pwInput.value !== pwConfirm.value) {
      errorEl.textContent = 'كلمتا السر غير متطابقتين';
      errorEl.classList.add('show');
      document.getElementById('wrap-reg-password-confirm').classList.add('has-error');
      return;
    }
    if (!terms.checked) {
      showToast('يرجى الموافقة على الشروط وسياسة الخصوصية للمتابعة', 'error');
      return;
    }

    btn.classList.add('loading');
    btn.disabled = true;
    const result = await UbourAuth.signUp({ phoneRaw: _pendingRegPhone, email, password: pwInput.value });
    btn.classList.remove('loading');
    btn.disabled = false;

    if (!result.ok) {
      if (result.error === 'DUPLICATE_PHONE') {
        showToast('هذا الرقم أصبح مسجّلاً للتو من جهاز آخر، يرجى تسجيل الدخول', 'error');
        showScreen('screen-login', { replace: true });
      } else if (result.error === 'DUPLICATE_EMAIL') {
        errorEl.textContent = 'هذا البريد الإلكتروني مسجّل بحساب من قبل';
        errorEl.classList.add('show');
      } else {
        showToast('حدث خطأ غير متوقع، حاول مرة أخرى', 'error');
      }
      return;
    }

    if (result.needsEmailConfirm) {
      document.getElementById('check-email-address').textContent = email;
      showScreen('screen-check-email', { replace: true });
    } else {
      // بعض مشاريع Supabase تُعطّل اشتراط تأكيد البريد — عندها تبدأ الجلسة فوراً
      showToast('تم إنشاء حسابك بنجاح 🎉', 'success');
      await routeUserAfterAuth();
    }
  }

  btn.addEventListener('click', submitRegisterAccount);
  pwConfirm.addEventListener('keydown', (e) => { if (e.key === 'Enter') submitRegisterAccount(); });

  document.getElementById('btn-check-email-continue').addEventListener('click', () => {
    showScreen('screen-login', { replace: true });
  });
  document.getElementById('btn-check-email-back').addEventListener('click', () => goBack('screen-register-account'));
}

/* =========================================================================
   شاشة: نسيت كلمة السر / تعيين كلمة سر جديدة
   ========================================================================= */
function initForgotPasswordScreen() {
  const phoneInput = document.getElementById('input-forgot-phone');
  const errorEl = document.getElementById('error-forgot-email');
  const btn = document.getElementById('btn-forgot-password-send');

  document.getElementById('btn-forgot-password-back').addEventListener('click', () => goBack('screen-login'));

  btn.addEventListener('click', async () => {
    const phoneRaw = phoneInput.value.trim();
    errorEl.classList.remove('show');
    if (!phoneRaw) {
      errorEl.textContent = 'يرجى إدخال رقم الجوال';
      errorEl.classList.add('show');
      return;
    }
    btn.classList.add('loading');
    btn.disabled = true;
    const result = await UbourAuth.requestPasswordResetByPhone(phoneRaw);
    btn.classList.remove('loading');
    btn.disabled = false;

    if (!result.ok) {
      if (result.error === 'PHONE_NOT_FOUND') {
        errorEl.textContent = 'هذا الرقم غير مسجّل في التطبيق';
      } else if (result.error === 'INVALID_PHONE') {
        errorEl.textContent = 'صيغة رقم الجوال غير صحيحة';
      } else {
        errorEl.textContent = 'تعذّر إرسال رابط الاستعادة، حاول مجدداً';
      }
      errorEl.classList.add('show');
      return;
    }
    showToast('إن كان الرقم مسجّلاً فسيصلك رابط استعادة كلمة السر على بريدك المسجّل', 'success', 5000);
    showScreen('screen-login', { replace: true });
  });
}

function initResetPasswordScreen() {
  const pwInput = document.getElementById('input-reset-password');
  const errorEl = document.getElementById('error-reset-password');
  const btn = document.getElementById('btn-reset-password-submit');

  document.getElementById('btn-reset-password-back').addEventListener('click', () => {
    showScreen('screen-login', { replace: true });
  });

  btn.addEventListener('click', async () => {
    errorEl.classList.remove('show');
    if (pwInput.value.length < 8) {
      errorEl.textContent = 'كلمة السر يجب ألا تقل عن 8 أحرف';
      errorEl.classList.add('show');
      return;
    }
    btn.classList.add('loading');
    btn.disabled = true;
    const result = await UbourAuth.updatePasswordAfterReset(pwInput.value);
    btn.classList.remove('loading');
    btn.disabled = false;

    if (!result.ok) {
      errorEl.textContent = 'تعذّر حفظ كلمة السر، حاول مجدداً';
      errorEl.classList.add('show');
      return;
    }
    showToast('تم تحديث كلمة السر بنجاح', 'success');
    await routeUserAfterAuth();
  });
}

/* ---------------- أدوات مشتركة ---------------- */
function currencyLabel(code) {
  const c = APP_CONFIG.currencies.find(x => x.code === code);
  return c ? c.label : code;
}
function bookingStatusLabel(s) {
  return { pending: 'قيد الانتظار', completed: 'مكتملة', cancel_requested: 'طلب إلغاء' }[s] || s;
}
function whatsappLink(phone, message) {
  const digits = normalizeDigits(phone || '').replace(/[^\d]/g, '');
  return `https://wa.me/${digits}?text=${encodeURIComponent(message)}`;
}
async function doLogout() {
  await UbourAuth.logout();
  _currentProfileCache = null;
  screenHistory.length = 0;
  screenHistory.push('screen-login');
  showScreen('screen-login', { replace: true });
  document.getElementById('input-login-phone').value = '';
  document.getElementById('input-login-password').value = '';
  showToast('تم تسجيل الخروج', 'info');
}
function initModals() {
  document.querySelectorAll('.modal-overlay').forEach(overlay => {
    overlay.addEventListener('click', (e) => { if (e.target === overlay) closeModals(); });
    overlay.querySelectorAll('[data-close-modal]').forEach(btn => btn.addEventListener('click', closeModals));
  });
}
function closeModals() {
  document.querySelectorAll('.modal-overlay').forEach(m => m.classList.remove('active'));
}

/* ---------------- التوجيه بعد الدخول/التسجيل حسب الدور ---------------- */
async function routeUserAfterAuth() {
  const profile = await UbourDB.getCurrentProfile();
  if (!profile) { showScreen('screen-login', { replace: true }); return; }

  const isAdmin = await UbourDB.isAdmin(profile.phone);
  if (isAdmin) {
    await renderAdminScreen();
    showScreen('screen-admin', { replace: true });
    return;
  }
  if (!profile.role) {
    showScreen('screen-role-select', { replace: true });
    return;
  }
  if (profile.role === 'traveler') {
    await renderTravelerScreen();
    showScreen('screen-traveler', { replace: true });
  } else if (profile.role === 'office') {
    await renderOfficeScreen();
    showScreen('screen-office', { replace: true });
  } else {
    showScreen('screen-role-select', { replace: true });
  }
}

/* =========================================================================
   شاشة 8: اختيار نوع الحساب
   ========================================================================= */
function initRoleSelectScreen() {
  // لا توجد خطوة "سابقة" منطقية هنا (الحساب أُنشئ بالفعل) — الرجوع يعني
  // تسجيل الخروج والعودة لبداية الدخول، بدل ترك المستخدم في حالة معلّقة
  document.getElementById('btn-role-select-back').addEventListener('click', doLogout);

  document.getElementById('btn-role-traveler').addEventListener('click', async () => {
    const userId = await UbourDB.getCurrentUserId();
    if (!userId) return;
    await UbourDB.setUserRole(userId, 'traveler');
    await renderTravelerScreen();
    showScreen('screen-traveler', { replace: true });
    showToast('مرحباً بك! تصفّح الرحلات المتاحة الآن', 'success');
  });
  document.getElementById('btn-role-office').addEventListener('click', () => {
    showScreen('screen-office-setup');
  });
}

/* =========================================================================
   شاشة 9: بيانات المكتب/السائق
   ========================================================================= */
let _selectedAccountType = null;
function initOfficeSetupScreen() {
  document.getElementById('btn-office-setup-back').addEventListener('click', () => goBack('screen-role-select'));

  document.querySelectorAll('#office-account-type-group [data-account-type]').forEach(btn => {
    btn.addEventListener('click', () => {
      document.querySelectorAll('#office-account-type-group [data-account-type]').forEach(b => {
        b.classList.remove('btn-gold'); b.classList.add('btn-ghost');
      });
      btn.classList.remove('btn-ghost'); btn.classList.add('btn-gold');
      _selectedAccountType = btn.dataset.accountType;
    });
  });

  const btn = document.getElementById('btn-office-setup-submit');
  const errorEl = document.getElementById('error-office-setup');
  btn.addEventListener('click', async () => {
    const name = document.getElementById('input-office-name').value.trim();
    const address = document.getElementById('input-office-address').value.trim();
    errorEl.classList.remove('show');

    if (!_selectedAccountType) {
      errorEl.textContent = 'يرجى اختيار نوع الحساب';
      errorEl.classList.add('show');
      return;
    }
    if (!name) {
      errorEl.textContent = 'يرجى إدخال الاسم';
      errorEl.classList.add('show');
      return;
    }
    const userId = await UbourDB.getCurrentUserId();
    if (!userId) return;

    btn.classList.add('loading'); btn.disabled = true;
    try {
      await UbourDB.createOffice({ userId, name, address, accountType: _selectedAccountType });
      await UbourDB.setUserRole(userId, 'office', name);
      btn.classList.remove('loading'); btn.disabled = false;
      await renderOfficeScreen();
      showScreen('screen-office', { replace: true });
      showToast('تم إنشاء حسابك بنجاح 🎉', 'success');
    } catch (e) {
      btn.classList.remove('loading'); btn.disabled = false;
      showToast('حدث خطأ، حاول مرة أخرى', 'error');
      console.error(e);
    }
  });
}

/* =========================================================================
   شاشة 10: لوحة المسافر
   ========================================================================= */
let _bookingTripId = null;
let _currentProfileCache = null; // يُحدَّث عند كل دخول للوحة لتفادي استعلامات متكررة

async function renderTravelerScreen() {
  const profile = await UbourDB.getCurrentProfile();
  if (!profile) return;
  _currentProfileCache = profile;
  document.getElementById('traveler-user-phone').textContent = profile.phone;
  document.getElementById('traveler-profile-phone').textContent = profile.phone;

  await renderTravelerTrips();
  await renderTravelerBookings();

  document.querySelectorAll('#screen-traveler .nav-item').forEach(n => n.classList.remove('active'));
  const firstTab = document.querySelector('#screen-traveler .nav-item[data-traveler-tab="search"]');
  if (firstTab) firstTab.classList.add('active');
  document.querySelectorAll('#screen-traveler .home-view').forEach(v => v.classList.add('hidden'));
  document.getElementById('traveler-view-search').classList.remove('hidden');
}

async function renderTravelerTrips(filterText) {
  const list = document.getElementById('traveler-trips-list');
  let trips = await UbourDB.getActiveTrips();
  if (filterText && filterText.trim()) {
    const f = filterText.trim();
    trips = trips.filter(t => t.from_place.includes(f) || t.to_place.includes(f));
  }
  if (!trips.length) {
    list.innerHTML = `<div class="empty-state">${ICONS.route}<div class="mt-2">لا توجد رحلات متاحة حالياً</div></div>`;
    return;
  }

  list.innerHTML = trips.map(t => {
    const office = t.office;
    const avatar = office && office.logo_url
      ? `<img src="${esc(office.logo_url)}" alt="" style="width:22px;height:22px;border-radius:50%;object-fit:cover;vertical-align:middle;margin-inline-end:6px;">`
      : '';
    return `
    <div class="list-card">
      <div class="lc-top">
        <span class="lc-sub">${avatar}${esc((office && office.name) || t.office_name)}</span>
        <span class="lc-price">${esc(t.price)} ${currencyLabel(t.currency)}</span>
      </div>
      <div class="lc-route">${ICONS.route}<span>${esc(t.from_place)}</span>${ICONS.chevron}<span>${esc(t.to_place)}</span></div>
      <div class="lc-meta">
        <span>${ICONS.clock}${esc(t.trip_date)} — ${esc(t.trip_time)}</span>
        <span>${ICONS.users} ${esc(t.seats_available)} مقعد متاح</span>
        ${t.vehicle_type ? `<span>${ICONS.bus} ${esc(t.vehicle_type)}</span>` : ''}
      </div>
      <div class="lc-actions">
        <button class="btn btn-primary" data-book-trip="${esc(t.id)}" style="margin-top:0;">حجز مقعد</button>
        <button class="whatsapp-btn" data-contact-trip="${esc(t.id)}" style="flex:0 0 auto; width:44px;">${ICONS.whatsapp}</button>
      </div>
    </div>
  `;
  }).join('');
  list.querySelectorAll('[data-book-trip]').forEach(btn => {
    btn.addEventListener('click', () => openBookingModal(btn.dataset.bookTrip));
  });
  list.querySelectorAll('[data-contact-trip]').forEach(btn => {
    btn.addEventListener('click', () => {
      const trip = trips.find(x => x.id === btn.dataset.contactTrip);
      if (!trip || !trip.office) return;
      const msg = APP_CONFIG.whatsappContactTemplate
        .replace('{trip}', `${trip.from_place} ← ${trip.to_place}`)
        .replace('{date}', trip.trip_date);
      openExternal(whatsappLink(trip.office.phone, msg));
    });
  });
}

async function renderTravelerBookings() {
  const profile = _currentProfileCache || await UbourDB.getCurrentProfile();
  const list = document.getElementById('traveler-bookings-list');
  if (!profile) { list.innerHTML = ''; return; }
  const bookings = await UbourDB.getBookingsByTraveler(profile.id);
  if (!bookings.length) {
    list.innerHTML = `<div class="empty-state">${ICONS.box}<div class="mt-2">لا توجد حجوزات بعد</div></div>`;
    return;
  }
  const rows = await Promise.all(bookings.slice().reverse().map(async (b) => {
    const trip = await UbourDB.getTripById(b.trip_id);
    if (!trip) return '';
    const tripOffice = await UbourDB.getProfileById(trip.office_id);
    const canCancel = b.status === 'pending';
    return `
      <div class="list-card">
        <div class="lc-top">
          <span class="lc-sub">${esc((tripOffice && tripOffice.name) || trip.office_name)}</span>
          <span class="badge-pill status-${esc(b.status)}">${bookingStatusLabel(b.status)}</span>
        </div>
        <div class="lc-route">${ICONS.route}<span>${esc(trip.from_place)}</span>${ICONS.chevron}<span>${esc(trip.to_place)}</span></div>
        <div class="lc-meta"><span>${ICONS.clock}${esc(trip.trip_date)} — ${esc(trip.trip_time)}</span><span>${esc(b.seats)} مقعد</span></div>
        ${b.status === 'cancel_requested' && b.cancel_reason ? `<div class="lc-sub" style="color:var(--error); margin-top:6px;">سبب الإلغاء: ${esc(b.cancel_reason)}</div>` : ''}
        ${canCancel ? `<div class="lc-actions"><button class="btn btn-ghost" data-cancel-booking="${esc(b.id)}" style="padding:10px; font-size:13px; color:var(--error); border-color:var(--error);">إلغاء الحجز</button></div>` : ''}
      </div>`;
  }));
  list.innerHTML = rows.join('');

  list.querySelectorAll('[data-cancel-booking]').forEach(btn => {
    btn.addEventListener('click', () => openCancelModal(btn.dataset.cancelBooking, 'traveler'));
  });
}

async function openBookingModal(tripId) {
  const trip = await UbourDB.getTripById(tripId);
  if (!trip) return;
  _bookingTripId = tripId;
  document.getElementById('book-trip-summary').textContent =
    `${trip.from_place} ← ${trip.to_place} | ${esc(trip.trip_date)} ${esc(trip.trip_time)} | ${esc(trip.price)} ${currencyLabel(trip.currency)} للمقعد الواحد`;
  const seatsInput = document.getElementById('input-booker-seats');
  seatsInput.value = 1;
  seatsInput.max = trip.seats_available;
  document.getElementById('modal-book-trip').classList.add('active');
}

/* ---------------- نافذة إلغاء الحجز/الرحلة (مشتركة بين المسافر والمكتب) ---------------- */
let _cancelContext = null; // { id, type: 'booking' | 'trip', initiator: 'traveler' | 'office' }
function openCancelModal(id, initiator, type) {
  _cancelContext = { id, initiator, type: type || 'booking' };
  document.getElementById('input-cancel-reason').value = '';
  document.getElementById('cancel-modal-title').textContent = _cancelContext.type === 'trip' ? 'إلغاء الرحلة' : 'إلغاء الحجز';
  document.getElementById('modal-cancel-booking').classList.add('active');
}
function initCancelModal() {
  document.getElementById('btn-submit-cancel').addEventListener('click', async () => {
    if (!_cancelContext) return;
    const reason = document.getElementById('input-cancel-reason').value.trim();
    if (!reason) { showToast('يرجى كتابة سبب الإلغاء', 'error'); return; }

    const { id, initiator, type } = _cancelContext;

    if (type === 'trip') {
      // إلغاء رحلة كاملة: تُلغى كل الحجوزات المرتبطة بها تلقائياً بنفس السبب
      const allBookings = await UbourDB.getAllBookings();
      const bookingsBefore = allBookings.filter(b => b.trip_id === id && b.status !== 'cancel_requested');
      const trip = await UbourDB.cancelTrip(id, reason);
      if (!trip) return;

      // إخطار أول مسافر حجز عبر واتساب (المتصفحات تمنع فتح أكثر من نافذة منبثقة تلقائياً لكل نقرة)
      if (bookingsBefore.length > 0) {
        const first = bookingsBefore[0];
        const msg = APP_CONFIG.whatsappCancelToTravelerTemplate
          .replace('{trip}', `${trip.from_place} ← ${trip.to_place}`).replace('{date}', trip.trip_date).replace('{reason}', reason);
        openExternal(whatsappLink(first.traveler_phone, msg));
      }
      const extra = bookingsBefore.length > 1 ? ` (يرجى إخطار باقي ${bookingsBefore.length - 1} مسافراً يدوياً عبر واتساب)` : '';
      showToast(`تم إلغاء الرحلة وكل حجوزاتها${extra}`, 'info', 6000);

      const profile = await UbourDB.getCurrentProfile();
      if (profile) { await renderOfficeTrips(profile); await renderOfficeRequests(profile); }
    } else {
      const booking = await UbourDB.cancelBooking(id, reason, initiator);
      if (!booking) return;
      const trip = await UbourDB.getTripById(booking.trip_id);
      const office = trip && await UbourDB.getProfileById(trip.office_id);

      if (initiator === 'traveler' && office) {
        const msg = APP_CONFIG.whatsappCancelToOfficeTemplate
          .replace('{trip}', `${trip.from_place} ← ${trip.to_place}`).replace('{date}', trip.trip_date).replace('{reason}', reason);
        openExternal(whatsappLink(office.phone, msg));
        await renderTravelerBookings();
      } else if (initiator === 'office') {
        const msg = APP_CONFIG.whatsappCancelToTravelerTemplate
          .replace('{trip}', `${trip.from_place} ← ${trip.to_place}`).replace('{date}', trip.trip_date).replace('{reason}', reason);
        openExternal(whatsappLink(booking.traveler_phone, msg));
        const profile = await UbourDB.getCurrentProfile();
        if (profile) await renderOfficeRequests(profile);
      }
      showToast('تم إرسال طلب الإلغاء', 'info');
    }

    closeModals();
    _cancelContext = null;
  });
}

function initTravelerScreen() {
  document.querySelectorAll('#screen-traveler .nav-item').forEach(item => {
    item.addEventListener('click', () => {
      document.querySelectorAll('#screen-traveler .nav-item').forEach(n => n.classList.remove('active'));
      item.classList.add('active');
      document.querySelectorAll('#screen-traveler .home-view').forEach(v => v.classList.add('hidden'));
      document.getElementById('traveler-view-' + item.dataset.travelerTab).classList.remove('hidden');
    });
  });

  document.getElementById('input-trip-search').addEventListener('input', (e) => renderTravelerTrips(e.target.value));

  document.getElementById('btn-support-send').addEventListener('click', async () => {
    const msgInput = document.getElementById('input-support-message');
    const msg = msgInput.value.trim();
    if (!msg) { showToast('اكتب رسالتك أولاً', 'error'); return; }
    const profile = await UbourDB.getCurrentProfile();
    if (!profile) return;
    await UbourDB.createSupportMessage({ fromId: profile.id, fromName: profile.name || profile.phone, fromPhone: profile.phone, message: msg });
    msgInput.value = '';
    showToast('تم إرسال رسالتك للدعم الفني', 'success');
  });

  document.getElementById('btn-traveler-logout').addEventListener('click', doLogout);

  document.getElementById('btn-confirm-booking-whatsapp').addEventListener('click', async () => {
    const trip = await UbourDB.getTripById(_bookingTripId);
    if (!trip) return;
    const name = document.getElementById('input-booker-name').value.trim();
    const seats = parseInt(normalizeDigits(document.getElementById('input-booker-seats').value), 10) || 0;

    if (!name) { showToast('يرجى إدخال اسمك', 'error'); return; }
    if (seats < 1 || seats > trip.seats_available) { showToast('عدد مقاعد غير صالح', 'error'); return; }

    const profile = await UbourDB.getCurrentProfile();
    if (!profile) return;
    try {
      await UbourDB.createBooking({ tripId: trip.id, travelerId: profile.id, travelerName: name, travelerPhone: profile.phone, seats });
    } catch (err) {
      const m = (err && err.message) || '';
      showToast(m.includes('NOT_ENOUGH_SEATS') ? 'عذراً، لم تعد المقاعد المطلوبة متاحة' : m.includes('TRIP_NOT_ACTIVE') ? 'هذه الرحلة لم تعد متاحة للحجز' : m.includes('TOO_MANY_OPEN_BOOKINGS') ? 'لديك حجوزات مفتوحة كثيرة، أكمل أو ألغِ بعضها أولاً' : m.includes('PHONE_REQUIRED') ? 'رقم هاتفك غير مكتمل في حسابك، تواصل مع الدعم' : 'تعذّر إتمام الحجز، حاول مرة أخرى', 'error');
      closeModals();
      await renderTravelerTrips();
      return;
    }

    const office = await UbourDB.getProfileById(trip.office_id);
    const msg = APP_CONFIG.whatsappBookingTemplate
      .replace('{trip}', `${trip.from_place} ← ${trip.to_place} بتاريخ ${esc(trip.trip_date)}`)
      .replace('{seats}', seats)
      .replace('{name}', name);
    if (office && office.phone) openExternal(whatsappLink(office.phone, msg));

    closeModals();
    await renderTravelerTrips();
    await renderTravelerBookings();
    showToast('تم تسجيل حجزك، أكمل التواصل عبر واتساب مع المكتب', 'success');
  });
}

/* =========================================================================
   شاشة 11: لوحة المكتب/السائق
   ========================================================================= */
async function renderOfficeScreen() {
  const office = await UbourDB.getCurrentProfile();
  if (!office) return;
  _currentProfileCache = office;

  document.getElementById('office-user-name').textContent = office.name;
  document.getElementById('office-profile-phone').textContent = office.phone;
  document.getElementById('office-profile-address').textContent = office.address || '—';
  const days = UbourDB.daysRemaining(office);
  const subActive = office.subscription_active && days > 0;
  document.getElementById('office-profile-subscription').textContent =
    subActive ? `فعّال (${days} يوم متبقي)` : 'منتهي';
  document.getElementById('subscription-renew-box').classList.toggle('hidden', subActive);

  document.getElementById('input-office-edit-name').value = office.name || '';
  const preview = document.getElementById('office-logo-preview');
  const placeholder = document.getElementById('office-logo-picker-placeholder');
  if (office.logo_url) {
    preview.src = office.logo_url;
    preview.classList.remove('hidden');
    placeholder.classList.add('hidden');
  } else {
    preview.classList.add('hidden');
    placeholder.classList.remove('hidden');
  }
  renderOfficeAvatar(office);

  await renderOfficeRequests(office);
  await renderOfficeTrips(office);

  document.querySelectorAll('#screen-office .nav-item').forEach(n => n.classList.remove('active'));
  const firstTab = document.querySelector('#screen-office .nav-item[data-office-tab="requests"]');
  if (firstTab) firstTab.classList.add('active');
  document.querySelectorAll('#screen-office .home-view').forEach(v => v.classList.add('hidden'));
  document.getElementById('office-view-requests').classList.remove('hidden');
}

function renderOfficeAvatar(office) {
  const wrap = document.getElementById('office-avatar-wrap');
  if (office.logo_url) {
    wrap.innerHTML = `<img src="${esc(office.logo_url)}" alt="شعار المكتب" style="width:100%;height:100%;object-fit:cover;border-radius:50%;">`;
  } else {
    wrap.innerHTML = `<span id="icon-office-avatar">${ICONS.userCircle}</span>`;
  }
}

async function renderOfficeRequests(office) {
  const list = document.getElementById('office-requests-list');
  // تُستبعد طلبات أي رحلة أُلغيت بالكامل من قائمة الطلبات النشطة (حُذفت "من خانة الطلبات")
  const allBookings = await UbourDB.getBookingsForOffice(office.id);
  const bookings = allBookings.filter(b => b.trips && b.trips.office_id === office.id);
  const withTrips = await Promise.all(
    bookings.filter(b => b.status !== undefined).map(async (b) => ({ b, trip: await UbourDB.getTripById(b.trip_id) }))
  );
  const active = withTrips.filter(({ trip }) => trip && trip.status !== 'cancelled');

  if (!active.length) {
    list.innerHTML = `<div class="empty-state">${ICONS.bell}<div class="mt-2">لا توجد طلبات حجز واردة بعد</div></div>`;
    return;
  }
  list.innerHTML = active.slice().reverse().map(({ b, trip }) => {
    const cancelled = b.status === 'cancel_requested';
    return `
      <div class="list-card">
        <div class="lc-top">
          <span class="lc-title">${esc(b.traveler_name)}</span>
          <span class="badge-pill status-${esc(b.status)}">${bookingStatusLabel(b.status)}</span>
        </div>
        <div class="lc-route">${ICONS.route}<span>${esc(trip.from_place)}</span>${ICONS.chevron}<span>${esc(trip.to_place)}</span></div>
        <div class="lc-meta"><span>${ICONS.clock}${esc(trip.trip_date)} — ${esc(trip.trip_time)}</span><span>${esc(b.seats)} مقعد</span>${trip.vehicle_type ? `<span>${ICONS.bus} ${esc(trip.vehicle_type)}</span>` : ''}</div>
        ${cancelled && b.cancel_reason ? `<div class="lc-sub" style="color:var(--error); margin-bottom:10px;">سبب الإلغاء: ${esc(b.cancel_reason)}</div>` : ''}
        <div class="lc-actions">
          ${!cancelled ? `<button class="whatsapp-btn" data-wa-booking="${esc(b.id)}">${ICONS.whatsapp}تواصل واتساب</button>` : ''}
          ${!cancelled && b.status !== 'completed' ? `<button class="icon-action-btn" data-cancel-booking="${esc(b.id)}" data-cancel-by="office" title="إلغاء الحجز">${ICONS.x}</button>` : ''}
        </div>
      </div>`;
  }).join('');

  list.querySelectorAll('[data-wa-booking]').forEach(btn => {
    btn.addEventListener('click', async () => {
      const allB = await UbourDB.getAllBookings();
      const booking = allB.find(x => x.id === btn.dataset.waBooking);
      if (!booking) return;
      const trip = await UbourDB.getTripById(booking.trip_id);
      const msg = `مرحباً ${booking.traveler_name}، بخصوص حجزك لرحلة ${trip.from_place} ← ${trip.to_place} بتاريخ ${esc(trip.trip_date)} (${booking.seats} مقعد) — نؤكد لك الحجز ✅`;
      openExternal(whatsappLink(booking.traveler_phone, msg));
      await UbourDB.updateBookingStatus(booking.id, 'completed');
      await renderOfficeRequests(office);
    });
  });
  list.querySelectorAll('[data-cancel-booking]').forEach(btn => {
    btn.addEventListener('click', () => openCancelModal(btn.dataset.cancelBooking, 'office'));
  });
}

function tripStatusLabel(status) {
  return { active: 'نشطة', inactive: 'غير نشطة', cancelled: 'ملغاة' }[status] || status;
}
async function renderOfficeTrips(office) {
  const list = document.getElementById('office-trips-list');
  const trips = await UbourDB.getTripsByOffice(office.id);
  if (!trips.length) {
    list.innerHTML = `<div class="empty-state">${ICONS.route}<div class="mt-2">لم تُضِف أي رحلة بعد</div></div>`;
    return;
  }
  list.innerHTML = trips.slice().reverse().map(t => `
    <div class="list-card">
      <div class="lc-top">
        <span class="badge-pill status-${t.status === 'active' ? 'active' : t.status === 'cancelled' ? 'cancel_requested' : 'inactive'}">${tripStatusLabel(t.status)}</span>
        <span class="lc-price">${esc(t.price)} ${currencyLabel(t.currency)}</span>
      </div>
      <div class="lc-route">${ICONS.route}<span>${esc(t.from_place)}</span>${ICONS.chevron}<span>${esc(t.to_place)}</span></div>
      <div class="lc-meta"><span>${ICONS.clock}${esc(t.trip_date)} — ${esc(t.trip_time)}</span><span>${esc(t.seats_available)}/${esc(t.seats_total)} مقعد متاح</span>${t.vehicle_type ? `<span>${ICONS.bus} ${esc(t.vehicle_type)}</span>` : ''}</div>
      ${t.status === 'cancelled' && t.cancel_reason ? `<div class="lc-sub" style="color:var(--error); margin-bottom:10px;">سبب الإلغاء: ${esc(t.cancel_reason)}</div>` : ''}
      <div class="lc-actions">
        ${t.status !== 'cancelled' ? `<button class="btn btn-ghost" data-edit-trip="${esc(t.id)}" style="padding:11px; font-size:13px; flex:1;">تعديل</button>` : ''}
        ${t.status === 'active' ? `<button class="btn btn-ghost" data-cancel-trip="${esc(t.id)}" style="padding:11px; font-size:13px; flex:1;">إلغاء الرحلة</button>` : ''}
        <button class="icon-action-btn" data-delete-trip="${esc(t.id)}">${ICONS.trash}</button>
      </div>
    </div>
  `).join('');
  list.querySelectorAll('[data-delete-trip]').forEach(btn => {
    btn.addEventListener('click', async () => {
      await UbourDB.deleteTrip(btn.dataset.deleteTrip);
      await renderOfficeTrips(office);
      showToast('تم حذف الرحلة', 'info');
    });
  });
  list.querySelectorAll('[data-cancel-trip]').forEach(btn => {
    btn.addEventListener('click', () => openCancelModal(btn.dataset.cancelTrip, 'office', 'trip'));
  });
  list.querySelectorAll('[data-edit-trip]').forEach(btn => {
    btn.addEventListener('click', () => openEditTripModal(trips.find(x => x.id === btn.dataset.editTrip)));
  });
}

/* ---- تعديل رحلة (للمكتب/السائق صاحب الرحلة فقط — تفرضه قاعدة البيانات أيضاً عبر RLS) ---- */
let _editingTrip = null;
const _TRIP_FIELD_IDS = ['input-trip-from', 'input-trip-to', 'input-trip-vehicle', 'input-trip-price', 'input-trip-seats', 'input-trip-date', 'input-trip-time'];
function _setTripModalMode(editing) {
  document.getElementById('add-trip-title').textContent = editing ? 'تعديل الرحلة' : 'إضافة رحلة جديدة';
  document.getElementById('add-trip-btn-label').textContent = editing ? 'حفظ التعديلات' : 'نشر الرحلة';
  document.getElementById('error-add-trip').classList.remove('show');
}
function openEditTripModal(trip) {
  if (!trip) return;
  _editingTrip = trip;
  _setTripModalMode(true);
  document.getElementById('input-trip-from').value = trip.from_place || '';
  document.getElementById('input-trip-to').value = trip.to_place || '';
  document.getElementById('input-trip-vehicle').value = trip.vehicle_type || '';
  document.getElementById('input-trip-price').value = trip.price;
  document.getElementById('select-trip-currency').value = trip.currency;
  document.getElementById('input-trip-seats').value = trip.seats_total;
  document.getElementById('input-trip-date').value = trip.trip_date;
  document.getElementById('input-trip-time').value = String(trip.trip_time || '').slice(0, 5);
  document.getElementById('modal-add-trip').classList.add('active');
}

function initOfficeScreen() {
  document.querySelectorAll('#screen-office .nav-item').forEach(item => {
    item.addEventListener('click', () => {
      document.querySelectorAll('#screen-office .nav-item').forEach(n => n.classList.remove('active'));
      item.classList.add('active');
      document.querySelectorAll('#screen-office .home-view').forEach(v => v.classList.add('hidden'));
      document.getElementById('office-view-' + item.dataset.officeTab).classList.remove('hidden');
    });
  });

  document.getElementById('btn-office-logout').addEventListener('click', doLogout);

  // طلب تجديد الاشتراك عبر واتساب — يتواصل مباشرة مع المدير الرئيسي؛
  // التجديد الفعلي وتحديد التواريخ يبقى بيد المدير حصرياً من لوحة الإدارة
  document.getElementById('btn-request-subscription').addEventListener('click', async () => {
    const primaryPhone = await UbourDB.getPrimaryManagerPhone();
    if (!primaryPhone) { showToast('تعذّر العثور على رقم الإدارة حالياً', 'error'); return; }
    const office = await UbourDB.getCurrentProfile();
    const msg = `مرحباً، أرغب بتجديد اشتراك حسابي "${office ? office.name : ''}" في ${APP_CONFIG.nameShort}.`;
    openExternal(whatsappLink(primaryPhone, msg));
  });

  // اقتراحات المدن/المناطق عبر datalist — لكن الحقل نص حر يقبل أي منطقة يكتبها
  // صاحب المكتب يدوياً حتى لو لم تكن ضمن القائمة (كما طُلب)
  const allPlaces = [...APP_CONFIG.yemenGovernorates, ...APP_CONFIG.saudiCities];
  document.getElementById('datalist-places').innerHTML = allPlaces.map(p => `<option value="${p}"></option>`).join('');
  document.getElementById('select-trip-currency').innerHTML = APP_CONFIG.currencies.map(c => `<option value="${c.code}">${c.label}</option>`).join('');
  document.getElementById('datalist-vehicle-types').innerHTML = APP_CONFIG.vehicleTypes.map(v => `<option value="${v}"></option>`).join('');

  document.getElementById('btn-open-add-trip').addEventListener('click', () => {
    _editingTrip = null;
    _setTripModalMode(false);
    _TRIP_FIELD_IDS.forEach(id => document.getElementById(id).value = '');
    document.getElementById('modal-add-trip').classList.add('active');
  });

  document.getElementById('btn-submit-add-trip').addEventListener('click', async () => {
    const from = document.getElementById('input-trip-from').value.trim();
    const to = document.getElementById('input-trip-to').value.trim();
    const vehicleType = document.getElementById('input-trip-vehicle').value.trim();
    const price = normalizeDigits(document.getElementById('input-trip-price').value).replace(/[^\d.]/g, '');
    const currency = document.getElementById('select-trip-currency').value;
    const seats = normalizeDigits(document.getElementById('input-trip-seats').value).replace(/\D/g, '');
    const date = document.getElementById('input-trip-date').value;
    const time = document.getElementById('input-trip-time').value;
    const errorEl = document.getElementById('error-add-trip');
    errorEl.classList.remove('show');

    if (!from || !to) { errorEl.textContent = 'يرجى تحديد نقطتي الانطلاق والوصول'; errorEl.classList.add('show'); return; }
    if (from === to) { errorEl.textContent = 'يجب أن تختلف نقطة الانطلاق عن الوصول'; errorEl.classList.add('show'); return; }
    if (!price || !seats || !date || !time) { errorEl.textContent = 'يرجى تعبئة جميع الحقول'; errorEl.classList.add('show'); return; }
    if (!(Number(price) > 0) || !(Number(seats) > 0) || !Number.isInteger(Number(seats))) { errorEl.textContent = 'يرجى إدخال قيم صحيحة للسعر وعدد المقاعد'; errorEl.classList.add('show'); return; }

    const office = await UbourDB.getCurrentProfile();
    if (!office) return;

    // وضع التعديل: تحديث الرحلة الحالية بدل إنشاء رحلة جديدة
    if (_editingTrip) {
      const booked = Number(_editingTrip.seats_total) - Number(_editingTrip.seats_available);
      if (Number(seats) < booked) {
        errorEl.textContent = 'لا يمكن أن يقل عدد المقاعد عن المقاعد المحجوزة حالياً (' + booked + ')';
        errorEl.classList.add('show');
        return;
      }
      try {
        await UbourDB.updateTrip(_editingTrip.id, {
          from_place: from, to_place: to, vehicle_type: vehicleType || null,
          price: Number(price), currency,
          seats_total: Number(seats), seats_available: Number(seats) - booked,
          trip_date: date, trip_time: time
        });
        _editingTrip = null;
        closeModals();
        await renderOfficeTrips(office);
        showToast(booked > 0 ? 'تم تحديث الرحلة — لديك حجوزات عليها، يُفضّل إبلاغ المسافرين بالتعديل' : 'تم تحديث الرحلة بنجاح', 'success');
      } catch (e) {
        showToast('تعذّر حفظ التعديلات، حاول مجدداً', 'error');
        console.error(e);
      }
      return;
    }

    try {
      await UbourDB.createTrip({ officeId: office.id, officeName: office.name, from, to, price, currency, seatsTotal: seats, date, time, vehicleType });
      closeModals();
      await renderOfficeTrips(office);
      showToast('تم نشر الرحلة بنجاح', 'success');
      ['input-trip-from', 'input-trip-to', 'input-trip-vehicle', 'input-trip-price', 'input-trip-seats', 'input-trip-date', 'input-trip-time'].forEach(id => document.getElementById(id).value = '');
    } catch (e) {
      showToast((e && (e.code === '42501' || /row-level security/i.test(String(e.message || '')))) ? 'اشتراكك منتهٍ أو غير مفعّل — تواصل مع الإدارة للتجديد' : 'تعذّر نشر الرحلة، حاول مجدداً', 'error');
      console.error(e);
    }
  });

  // اختيار شعار من ملفات الجهاز مباشرة (بدل كتابة رابط) — يُصغَّر تلقائياً
  // ليبقى حجمه معقولاً قبل حفظه، ويُعرض كمعاينة فورية
  let _pendingLogoDataUrl = null;
  document.getElementById('btn-pick-office-logo').addEventListener('click', () => {
    document.getElementById('input-office-logo-file').click();
  });
  document.getElementById('input-office-logo-file').addEventListener('change', (e) => {
    const file = e.target.files && e.target.files[0];
    if (!file) return;
    if (!file.type.startsWith('image/')) { showToast('يرجى اختيار ملف صورة', 'error'); return; }

    const reader = new FileReader();
    reader.onload = (ev) => {
      const img = new Image();
      img.onload = () => {
        const maxDim = 300;
        let w = img.width, h = img.height;
        if (w > h && w > maxDim) { h = Math.round(h * maxDim / w); w = maxDim; }
        else if (h > maxDim) { w = Math.round(w * maxDim / h); h = maxDim; }
        const canvas = document.createElement('canvas');
        canvas.width = w; canvas.height = h;
        canvas.getContext('2d').drawImage(img, 0, 0, w, h);
        _pendingLogoDataUrl = canvas.toDataURL('image/jpeg', 0.85);

        const preview = document.getElementById('office-logo-preview');
        preview.src = _pendingLogoDataUrl;
        preview.classList.remove('hidden');
        document.getElementById('office-logo-picker-placeholder').classList.add('hidden');
      };
      img.src = ev.target.result;
    };
    reader.readAsDataURL(file);
  });

  // حفظ اسم/شعار المكتب أو السائق — قابل للتعديل في أي وقت كما طُلب
  document.getElementById('btn-save-office-profile').addEventListener('click', async () => {
    const office = await UbourDB.getCurrentProfile();
    if (!office) return;
    const name = document.getElementById('input-office-edit-name').value.trim();
    if (!name) { showToast('يرجى إدخال الاسم', 'error'); return; }
    const patch = { name };
    // ملاحظة هامة: صورة الشعار محفوظة هنا كنص Base64 طويل مباشرة في عمود
    // logo_url (كما كانت في النسخة التجريبية السابقة). هذا يعمل، لكن الأصح
    // للإنتاج الحقيقي رفعها كملف إلى Supabase Storage وحفظ رابط قصير فقط —
    // خطوة تحسين لاحقة، وليست عائقاً أمام عمل الميزة الآن.
    if (_pendingLogoDataUrl) patch.logo_url = _pendingLogoDataUrl;
    try {
      const updated = await UbourDB.updateOffice(office.id, patch);
      document.getElementById('office-user-name').textContent = name;
      renderOfficeAvatar(updated);
      _pendingLogoDataUrl = null;
      showToast('تم حفظ التعديلات', 'success');
    } catch (e) {
      showToast('تعذّر حفظ التعديلات', 'error');
      console.error(e);
    }
  });

  // إرسال رسالة دعم فني من المكتب/السائق
  document.getElementById('btn-office-support-send').addEventListener('click', async () => {
    const msgInput = document.getElementById('input-office-support-message');
    const msg = msgInput.value.trim();
    if (!msg) { showToast('اكتب رسالتك أولاً', 'error'); return; }
    const office = await UbourDB.getCurrentProfile();
    if (!office) return;
    await UbourDB.createSupportMessage({ fromId: office.id, fromName: office.name || office.phone, fromPhone: office.phone, message: msg });
    msgInput.value = '';
    showToast('تم إرسال رسالتك للدعم الفني', 'success');
  });
}

